$ErrorActionPreference="Stop";$R="https://raw.githubusercontent.com/alamaxjashek/OfficeDeploy/main";$D="$env:ProgramData\OfficeDeploy";New-Item $D -ItemType Directory -Force|Out-Null;Invoke-WebRequest "$R/setup.exe" -OutFile "$D/setup.exe";Invoke-WebRequest "$R/install-m365.xml" -OutFile "$D/install-m365.xml";$P=Start-Process "$D/setup.exe" -ArgumentList "/configure `"$D\install-m365.xml`"" -Wait -PassThru;exit $P.ExitCode
